-- Feed existing Cajas / Inicio / fiscal reports from native close actions, without double counting.
alter table public.ops_daily_closings drop constraint if exists ops_daily_closings_source_check;
alter table public.ops_daily_closings add constraint ops_daily_closings_source_check check(source in('manual','importacion_excel','totustpv'));
create or replace function private.totus_native_closing_projection() returns trigger language plpgsql security definer set search_path='' as $$
declare day date;closing uuid;existing_source text;d record;first_session private.totus_tpv_local_sessions;last_session private.totus_tpv_local_sessions;pay jsonb;refund jsonb;incoming numeric;outgoing numeric;total_sales numeric;opening_total numeric:=0;closing_total numeric:=0;cash_total numeric:=0;card_total numeric:=0;bizum_total numeric:=0;other_total numeric:=0;incoming_total numeric:=0;outgoing_total numeric:=0;difference_total numeric:=0;
begin
 if old.closed_at is not null or new.closed_at is null then return new;end if;
 day:=(new.closed_at at time zone 'Europe/Madrid')::date;
 perform pg_advisory_xact_lock(hashtextextended('native-daily-closing:'||new.store_id::text||':'||day::text,0));
 select id,source into closing,existing_source from public.ops_daily_closings where store_id=new.store_id and business_date=day for update;
 if closing is not null and existing_source<>'totustpv' then raise exception 'Ya existe un cierre manual de esta tienda y fecha. Revísalo en Cajas antes de cerrar para no duplicar los ingresos.';end if;
 if closing is null then insert into public.ops_daily_closings(store_id,business_date,source,source_ref,created_by,closed_by,status,notes) values(new.store_id,day,'totustpv','totustpv:'||new.store_id::text||':'||day::text,auth.uid(),auth.uid(),'cerrado','Generado al cerrar las cajas de TotusTPV.') returning id into closing;end if;
 for d in select distinct drawer_id from private.totus_tpv_local_sessions where store_id=new.store_id and (closed_at at time zone 'Europe/Madrid')::date=day loop
  select * into first_session from private.totus_tpv_local_sessions where store_id=new.store_id and drawer_id=d.drawer_id and (closed_at at time zone 'Europe/Madrid')::date=day order by opened_at,id limit 1;
  select * into last_session from private.totus_tpv_local_sessions where store_id=new.store_id and drawer_id=d.drawer_id and (closed_at at time zone 'Europe/Madrid')::date=day order by closed_at desc,id desc limit 1;
  select coalesce(jsonb_object_agg(method,total),'{}') into pay from(select p.method,sum(p.amount_cents)/100.0 total from private.totus_tpv_local_payments p join private.totus_tpv_local_sessions s on s.id=p.session_id where s.store_id=new.store_id and s.drawer_id=d.drawer_id and (s.closed_at at time zone 'Europe/Madrid')::date=day group by p.method)x;
  select coalesce(jsonb_object_agg(method,total),'{}') into refund from(select p->>'method' method,sum((p->>'amountCents')::bigint)/100.0 total from private.totus_tpv_local_refunds f cross join lateral jsonb_array_elements(f.payments) p join private.totus_tpv_local_sessions s on s.id=f.session_id where s.store_id=new.store_id and s.drawer_id=d.drawer_id and (s.closed_at at time zone 'Europe/Madrid')::date=day and f.status='confirmed' group by p->>'method')x;
  select coalesce(sum(m.amount_cents)filter(where m.kind='in'),0)/100.0,coalesce(sum(m.amount_cents)filter(where m.kind='out'),0)/100.0 into incoming,outgoing from private.totus_tpv_local_cash_moves m join private.totus_tpv_local_sessions s on s.id=m.session_id where s.store_id=new.store_id and s.drawer_id=d.drawer_id and (s.closed_at at time zone 'Europe/Madrid')::date=day;
  total_sales:=coalesce((pay->>'cash')::numeric,0)-coalesce((refund->>'cash')::numeric,0)+coalesce((pay->>'card')::numeric,0)-coalesce((refund->>'card')::numeric,0)+coalesce((pay->>'bizum')::numeric,0)-coalesce((refund->>'bizum')::numeric,0)+coalesce((pay->>'transfer')::numeric,0)-coalesce((refund->>'transfer')::numeric,0)+coalesce((pay->>'cheque')::numeric,0)-coalesce((refund->>'cheque')::numeric,0);
  insert into public.ops_daily_closing_drawers(closing_id,drawer_id,opening_cash,closing_cash,card_sales,bizum_sales,online_sales,other_income,cash_withdrawals,cash_expenses_declared,cash_extra_in,cash_extra_out,reported_total_sales,notes)
   values(closing,d.drawer_id,first_session.opening_cents/100.0,last_session.counted_cents/100.0,coalesce((pay->>'card')::numeric,0)-coalesce((refund->>'card')::numeric,0),coalesce((pay->>'bizum')::numeric,0)-coalesce((refund->>'bizum')::numeric,0),0,coalesce((pay->>'transfer')::numeric,0)-coalesce((refund->>'transfer')::numeric,0)+coalesce((pay->>'cheque')::numeric,0)-coalesce((refund->>'cheque')::numeric,0),0,0,incoming,outgoing,case when total_sales>=0 then total_sales else null end,'TotusTPV · sesiones cerradas del día')
   on conflict(closing_id,drawer_id) do update set opening_cash=excluded.opening_cash,closing_cash=excluded.closing_cash,card_sales=excluded.card_sales,bizum_sales=excluded.bizum_sales,other_income=excluded.other_income,cash_extra_in=excluded.cash_extra_in,cash_extra_out=excluded.cash_extra_out,reported_total_sales=excluded.reported_total_sales;
  opening_total:=opening_total+first_session.opening_cents/100.0;closing_total:=closing_total+last_session.counted_cents/100.0;
  cash_total:=cash_total+coalesce((pay->>'cash')::numeric,0)-coalesce((refund->>'cash')::numeric,0);card_total:=card_total+coalesce((pay->>'card')::numeric,0)-coalesce((refund->>'card')::numeric,0);bizum_total:=bizum_total+coalesce((pay->>'bizum')::numeric,0)-coalesce((refund->>'bizum')::numeric,0);other_total:=other_total+coalesce((pay->>'transfer')::numeric,0)-coalesce((refund->>'transfer')::numeric,0)+coalesce((pay->>'cheque')::numeric,0)-coalesce((refund->>'cheque')::numeric,0);incoming_total:=incoming_total+incoming;outgoing_total:=outgoing_total+outgoing;
 end loop;
 update public.ops_daily_closings set opening_cash=opening_total,cash_sales=cash_total,card_sales=card_total,bizum_sales=bizum_total,other_income=other_total,cash_extra_in=incoming_total,cash_extra_out=outgoing_total,expected_cash=opening_total+cash_total+incoming_total-outgoing_total,actual_cash=closing_total,difference=closing_total-(opening_total+cash_total+incoming_total-outgoing_total),reported_total_sales=cash_total+card_total+bizum_total+other_total,status=case when exists(select 1 from private.totus_tpv_local_sessions where store_id=new.store_id and closed_at is null) then 'borrador' else 'cerrado' end,closed_by=auth.uid(),updated_at=now() where id=closing;
 return new;
end $$;
revoke all on function private.totus_native_closing_projection() from public,anon,authenticated;
drop trigger if exists native_closing_projection on private.totus_tpv_local_sessions;
create trigger native_closing_projection after update on private.totus_tpv_local_sessions for each row execute function private.totus_native_closing_projection();
